Plugins.Require("pay_activity", "common.config.LimitedTimeWeekGiftConfig")
---@type IPayActivity
local IPayActivity = Plugins.Require("pay_activity", "common.class.IPayActivity")
---@class LimitedTimeWeekGift : IPayActivity
local LimitedTimeWeekGift = class("LimitedTimeWeekGift", IPayActivity)
---@type LimitedTimeWeekGiftConfig
local LimitedTimeWeekGiftConfig = T(Global, "LimitedTimeWeekGiftConfig")
---@type PayActivityRewardConfig
local PayActivityRewardConfig = T(Global, "PayActivityRewardConfig")
---@type SPidPacketSender
local SPidPacketSender = T(Global, "PidPacketSender")
---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")
---@type EventConfig
local EventConfig = T(Global, "EventConfig")
EventConfig:registerEvent("limited_time_week_click", {})
EventConfig:registerEvent("limited_time_week_gift_get", {
    ["limited_time_week_gift_count"] = "number",
    ["limited_time_week_gift_id"] = "number",
})

function LimitedTimeWeekGift:initDataInfo()
    self:initInfoKey("WeekRecord", {})
    self:initInfoKey("WeekRoundId", 1)
    self:initInfoKey("WeekNextRoundDate", 0)
    self:initInfoKey("LimitedTimeWeek", isClient)
    if isClient then
        self:updateRedDot(self:isShowRedDot())
        self.info:addKeyObserver("WeekRecord", function()
            self:updateRedDot(self:isShowRedDot())
        end)
        self.info:addKeyObserver("WeekRoundId", function()
            self:updateRedDot(self:isShowRedDot())
        end)
    else
        self:registerC2SFunc("tryBuy")
    end
end

function LimitedTimeWeekGift:setSaveDBData(data)
    IPayActivity.setSaveDBData(self, data)
    if not isClient then
        self:changeRound()
    end
end

function LimitedTimeWeekGift:getLastWeekTime()
    local curTime = os.date("*t")
    local today = os.time({ year = curTime.year, month = curTime.month, day = curTime.day, hour = 0, min = 0, second = 0 })
    local wday = curTime.wday - 1
    if wday <= 0 then
        wday = 7
    end
    return today + (7 - wday + 1) * 86400
end

function LimitedTimeWeekGift:getCurRound()
    local startDate = os.date("*t", self.cfg.startDate)
    local countdown = os.time() - self.cfg.startDate
    local days = math.floor(countdown / 3600.0 / 24.0) + 1
    local startWday = startDate.wday
    local curRoundCount = math.max(math.ceil((days - (7 - startWday)) / 7), 1)
    local curRoundId = (curRoundCount % self:getMaxRound())
    if curRoundId == 0 then
        curRoundId = self:getMaxRound()
    end
    return curRoundId
end

function LimitedTimeWeekGift:changeRound()

    local curRoundId = self:getCurRound()
    local nextRoundDate = self:getLastWeekTime()
    local curRoundDate = self.info:getValue("WeekNextRoundDate")

    if curRoundDate ~= nextRoundDate then
        self.info:setValue("WeekNextRoundDate", nextRoundDate)
        self.info:setValue("WeekRoundId", curRoundId)
        self.info:setValue("WeekRecord", {})
    end
    LuaTimer:cancel(self.countdownTimer)
    local timeLeft = math.max((nextRoundDate - os.time()) * 1000, 1000)
    self.countdownTimer = LuaTimer:schedule(function()
        self:changeRound()
    end, timeLeft)
end

function LimitedTimeWeekGift:onStop()
    if isClient then
        self:updateRedDot(false)
        return
    end
    LuaTimer:cancel(self.countdownTimer)
    self.countdownTimer = nil
end

function LimitedTimeWeekGift:tryBuy(configId)
    local record = self.info:getValue("WeekRecord")
    local config = self:getConfig(configId)
    if not config then
        return
    end
    local buyCount = record[config.giftKey] or 0
    if buyCount >= config.limitCounts then
        return
    end
    if isClient then
        PayHelper.checkMoney(CurrencyId.GCube, config.finalPrice, function(success)
            if success then
                self:runServerFunc("tryBuy", configId)
            end
        end)
    else

        local countdown = self.cfg.endDate - os.time()
        if countdown <= 0 then
            return
        end

        if not self:canReward(config.giftContent) then
            --SPidPacketSender:sendShowToast(self.player.rakssid, "common.activity.tip.needBackPack")
            return
        end

        --先限制购买次数，失败再回滚
        record[config.giftKey] = buyCount + 1
        self.info:setValue("WeekRecord", record)
        PayHelper.payMoneySync(self.player, config.id, CurrencyId.GCube, config.finalPrice, function()
            self:doReward(config.giftContent, "GUILimitedTimeActivityRewardResult")
            local _record = self.info:getValue("WeekRecord")
            local _buyCount = (_record[config.giftKey] or 1)
            ReportEvent.reportEvent(self.player.userId, "limited_time_week_gift_get", false, {
                limited_time_week_gift_count = _buyCount,
                limited_time_week_gift_id = config.id,
            })
        end, function()
            local _record = self.info:getValue("WeekRecord")
            local _buyCount = (_record[config.giftKey] or 0)
            if _buyCount ~= 0 then
                _buyCount = _buyCount - 1
            end
            _record[config.giftKey] = _buyCount
            self.info:setValue("WeekRecord", _record)
        end)
    end
end

function LimitedTimeWeekGift:getConfig(id)
    return LimitedTimeWeekGiftConfig:getConfigById(id)
end

function LimitedTimeWeekGift:getMaxRound(id)
    return LimitedTimeWeekGiftConfig:getMaxRound(id)
end

function LimitedTimeWeekGift:isShowRedDot()
    local weekRoundId = self.info:getValue("WeekRoundId")
    local configs = LimitedTimeWeekGiftConfig:getCfgsByRoundId(weekRoundId)
    for _, item in pairs(configs) do
        if item.finalPrice <= 0 then
            local record = self.info:getValue("WeekRecord")
            local buyCount = record[item.giftKey] or 0
            return buyCount < item.limitCounts
        end
    end
    return false
end

return LimitedTimeWeekGift